"""Small exhaustive check of the orbit-counting inequality on a tractable action.

For n<=4 the space of Boolean cubic forms is small enough to enumerate the full
GL(n,2) action by brute force, verifying that the exact orbit count always lies in
the proven window [ceil((#forms-1)/|GL|), #forms-1] for nonzero orbits.
"""
from __future__ import annotations
from itertools import product, combinations
from math import comb


def gl_matrices(n: int) -> list[tuple[tuple[int, ...], ...]]:
    """All invertible n x n matrices over GF(2), as tuples of rows."""
    mats: list[tuple[tuple[int, ...], ...]] = []
    rows_all = list(product((0, 1), repeat=n))
    for M in product(rows_all, repeat=n):
        if _rank_gf2(M, n) == n:
            mats.append(M)
    return mats


def _rank_gf2(M: tuple[tuple[int, ...], ...], n: int) -> int:
    rows = [list(r) for r in M]
    rank = 0
    for col in range(n):
        piv = next((r for r in range(rank, n) if rows[r][col]), None)
        if piv is None:
            continue
        rows[rank], rows[piv] = rows[piv], rows[rank]
        for r in range(n):
            if r != rank and rows[r][col]:
                rows[r] = [(a ^ b) for a, b in zip(rows[r], rows[rank])]
        rank += 1
    return rank


def apply_matrix(M: tuple[tuple[int, ...], ...], f: dict, n: int) -> dict:
    """Substitute x_i -> sum_j M[i][j] x_j into a cubic form, reduce mod 2."""
    triples = list(combinations(range(n), 3))
    out: dict = {t: 0 for t in triples}
    for t, c in f.items():
        if not c:
            continue
        # image of x_a x_b x_c as a set of monomials (squarefree, mod 2)
        a, b, cc = t
        terms: dict = {}
        for ia in range(n):
            if not M[a][ia]:
                continue
            for ib in range(n):
                if not M[b][ib]:
                    continue
                for ic in range(n):
                    if not M[cc][ic]:
                        continue
                    s = frozenset((ia, ib, ic))
                    if len(s) == 3:  # squarefree survivors
                        terms[s] = terms.get(s, 0) ^ 1
        for s, v in terms.items():
            if v:
                key = tuple(sorted(s))
                out[key] ^= 1
    return out


def count_orbits(n: int) -> int:
    triples = list(combinations(range(n), 3))
    forms = [dict(zip(triples, bits)) for bits in product((0, 1), repeat=len(triples))]
    mats = gl_matrices(n)
    seen: set = set()
    orbits = 0
    for f in forms:
        key = tuple(f[t] for t in triples)
        if key in seen:
            continue
        orbits += 1
        for M in mats:
            g = apply_matrix(M, f, n)
            seen.add(tuple(g[t] for t in triples))
    return orbits


if __name__ == "__main__":
    for n in range(3, 5):
        total = count_orbits(n)
        nonzero = total - 1
        forms = 2 ** comb(n, 3)
        order = 1
        for i in range(n):
            order *= 2**n - 2**i
        floor_nz = -(-(forms - 1) // order)
        print(f"n={n}: exact nonzero orbits={nonzero}, floor={floor_nz}, "
              f"in window={floor_nz <= nonzero <= forms - 1}")
        assert floor_nz <= nonzero <= forms - 1
    print("orbit-counting window verified exhaustively for n=3,4")

