function GL_ORDER(n, q):
    order <- 1
    for i from 0 to n-1:
        order <- order * (q^n - q^i)
    return order

function PIGEONHOLE_FLOOR(n, d, q):
    forms <- q^C(n,d)
    order <- GL_ORDER(n, q)
    return CEIL_DIV(forms - 1, order)

