function WINDOW_REPORT(n, d, q, proposed):
    forms <- q^C(n,d)
    floor <- PIGEONHOLE_FLOOR(n, d, q)
    fits  <- (floor <= proposed) and (proposed <= forms - 1)
    return { lower: floor, upper: forms - 1,
             fits: fits, defect: proposed - floor,
             ratio: proposed / floor }
